/** Whether `exception` lets through the kind `kind` (no `path`), or the key path `path` of it, which the recordings lack. */
const covers = (exception: Exception, kind: string, path?: string): boolean => {
  if (exception.kind !== kind || exception.type !== undefined) return false
  if (exception.path === undefined) return true
  if (path === undefined) return false
  return path === exception.path || path.startsWith(`${exception.path}.`) || path.startsWith(`${exception.path}[`) || path.startsWith(`${exception.path}(`)
}

/** Whether `exception` lets through the JSON type `type` at exactly the key path `path` of the kind `kind`. */
const coversType = (exception: Exception, kind: string, path: string, type: string): boolean => exception.kind === kind && exception.path === path && exception.type === type

/**
 * Each kind, key path and JSON type at a key path of `played` the recordings lack, one line each with
 * where it is played; and the exceptions used.
 */
function inventedShapes(played: readonly Played[], recorded: Record<string, Shape>, exceptions: readonly Exception[]) {
  const invented: string[] = []
  const used = new Set<Exception>()
  const excused = (matches: (candidate: Exception) => boolean): boolean => {
    const exception = exceptions.find(matches)
    if (exception !== undefined) used.add(exception)
    return exception !== undefined
  }
  for (const { where, step } of played) {
    const kind = kindOf(step)
    const known = recorded[kind]
    if (known === undefined) {
      if (!excused((candidate) => covers(candidate, kind))) invented.push(`${where}: ${kind} — no recorded message of this kind`)
      continue
    }
    for (const [path, types] of Object.entries(shapeOf(bodyOf(step)))) {
      const recordedTypes = known[path]
      if (recordedTypes === undefined) {
        if (!excused((candidate) => covers(candidate, kind, path))) invented.push(`${where}: ${kind} ${path} — no recorded ${kind} has this key`)
        continue
      }
      for (const type of types) {
        if (!recordedTypes.includes(type) && !excused((candidate) => coversType(candidate, kind, path, type))) {
          invented.push(`${where}: ${kind} ${path} is ${type} — every recorded ${kind} has ${recordedTypes.join(' or ')} here`)
        }
      }
    }
  }
  return { invented, used }
}

/** Every step of the fake's scripts, as they are written. */
const scriptSteps = (): Played[] =>
  readdirSync(SCRIPTS)
    .filter((name) => name.endsWith('.jsonl'))
    .sort()
    .flatMap((name) => readSteps(join(SCRIPTS, name), name))

/** An exit step of the fake (worfy-faults ticket 06): an exit code alone, `{"exit": 1}`. It plays no message. */
const isExitStep = (step: Step): boolean => Object.keys(step).length === 1 && Number.isInteger(step.exit)

/** The steps that carry "exit" and are not an exit step: the fake refuses them, and so does this suite. */
const exitProblems = (played: readonly Played[]): string[] =>
  played.filter(({ step }) => 'exit' in step && !isExitStep(step)).map(({ where }) => `${where}: an "exit" step is {"exit": <exit code>} alone`)

/** The steps that play a message: an exit step has nothing to compare and is left out. */
const messageSteps = (played: readonly Played[]): Played[] => played.filter(({ step }) => !isExitStep(step))

/** Every step of the fake's scripts that plays a message. */
const fakeSteps = (): Played[] => messageSteps(scriptSteps())

describe('the pinned Codex and its recorded messages', () => {
  it('the recordings are of the pinned Codex, pass its JSON Schema and have every shape the fake plays', () => {
    const recordings = readRecordings(RECORDINGS)
    // Without recordings of this version nothing below means anything: stop here, naming the owner's command.
    expect(versionProblems(recordings, pinnedCodex(), installedCodex())).toEqual([])
    expect.soft(schemaProblems(recordings.steps)).toEqual([])
    expect.soft(hookProblems(readHooks(recordings.folder))).toEqual([])
    const played = fakeSteps()
    expect(played.length).toBeGreaterThan(0)
    expect.soft(exitProblems(scriptSteps())).toEqual([])
    const { invented, used } = inventedShapes(played, shapesByKind(recordings.steps), EXCEPTIONS)
    expect.soft(invented).toEqual([])
    expect.soft(EXCEPTIONS.filter((exception) => !used.has(exception)).map(({ kind, path }) => `${kind} ${path ?? ''}: no script needs this exception`)).toEqual([])
  })
})

